begin;
create extension if not exists pgtap with schema extensions;
select plan(18);
select ok((select pg_get_constraintdef(oid) like '%admin.invite%' from pg_constraint where conname='admin_approval_requests_action_type_check'), 'invite approval catalog action exists');
select ok((select pg_get_constraintdef(oid) like '%admin.deactivate%' from pg_constraint where conname='admin_approval_requests_action_type_check'), 'deactivate approval catalog action exists');
select function_returns('public','apply_approved_admin_role_change',array['uuid'],'jsonb','role apply RPC exists');
select function_returns('public','apply_approved_admin_deactivate',array['uuid'],'jsonb','deactivate apply RPC exists');
select ok((select pg_get_functiondef('public.apply_approved_admin_role_change(uuid)'::regprocedure) like '%APPROVER_MUST_DIFFER%'), 'role apply requires a different approver');
select ok((select pg_get_functiondef('public.apply_approved_admin_role_change(uuid)'::regprocedure) like '%SELF_ROLE_CHANGE_FORBIDDEN%'), 'self role change is blocked');
select ok((select pg_get_functiondef('public.apply_approved_admin_role_change(uuid)'::regprocedure) like '%LAST_OWNER_FORBIDDEN%'), 'last owner removal is blocked');
select ok((select pg_get_functiondef('public.apply_approved_admin_deactivate(uuid)'::regprocedure) like '%SELF_DEACTIVATE_FORBIDDEN%'), 'self deactivation is blocked');
select ok((select pg_get_functiondef('public.apply_approved_admin_deactivate(uuid)'::regprocedure) like '%session_state%'), 'deactivation reports revocation pending state');
select ok((select pg_get_functiondef('public.apply_approved_admin_role_change(uuid)'::regprocedure) like '%require_current_operator_aal2_actor%'), 'role apply requires AAL2');
select ok((select pg_get_functiondef('public.apply_approved_admin_deactivate(uuid)'::regprocedure) like '%require_current_operator_aal2_actor%'), 'deactivate apply requires AAL2');
select ok(not has_function_privilege('anon','public.apply_approved_admin_role_change(uuid)','EXECUTE'),'anon cannot apply role change');
select ok(not has_function_privilege('service_role','public.apply_approved_admin_role_change(uuid)','EXECUTE'),'service role cannot apply role change directly');
select ok(not has_table_privilege('authenticated','public.admin_invite_intents','INSERT,UPDATE,DELETE'),'invite intent is not directly mutable');
select ok((select pg_get_functiondef('public.apply_approved_admin_deactivate(uuid)'::regprocedure) !~ '(password|token|secret|email)'), 'deactivate apply exposes no credentials');
select ok((select pg_get_constraintdef(oid) like '%admin.role.change.workspace.applied%' from pg_constraint where conname='platform_audit_events_action_check'), 'role applied audit action is allowlisted');
select ok((select pg_get_constraintdef(oid) like '%admin.invite.approved%' from pg_constraint where conname='platform_audit_events_action_check'), 'invite approval audit action is allowlisted');
select ok((select pg_get_constraintdef(oid) like '%admin.deactivate.applied%' from pg_constraint where conname='platform_audit_events_action_check'), 'deactivate applied audit action is allowlisted');
select * from finish(); rollback;
